#pragma once

namespace perfetto
{
    class TracingSession;
}

#include <perfetto.h>

PERFETTO_DEFINE_CATEGORIES(
    perfetto::Category("FREYR").SetDescription(
        "Events generated by the Freyr internal execution"),
    perfetto::Category("USER").SetDescription(
        "Events generated by the User code execution"));

#define USER_TRACE_BEGIN(name, ...) \
    TRACE_EVENT_BEGIN("USER", name, __VA_ARGS__)
#define USER_TRACE_END(...) \
    TRACE_EVENT_END("USER", __VA_ARGS__)

PERFETTO_TRACK_EVENT_STATIC_STORAGE();